package build

// Purpose: prove cleanupProviderOutput deletes only what the traefik renderer
// wrote (EPIC DEPL D4) and never anything else.

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

const testRendererMarker = "GENERATED BY nself traefik renderer - DO NOT HAND EDIT\n"

// restoreProject builds a project tree with a traefik output dir and a sibling
// generated file that must survive every cleanup.
func restoreProject(t *testing.T, marker string) (workdir, dir string) {
	t.Helper()
	workdir = t.TempDir()
	dir = proxyOutputDir(workdir)
	writeFixtureFile(t, filepath.Join(dir, "dynamic.yml"), "# fixture\n", 0644)
	writeFixtureFile(t, filepath.Join(dir, "sub", "static.yml"), "# fixture\n", 0644)
	if marker != "" {
		writeFixtureFile(t, filepath.Join(dir, proxyGeneratedMarker), marker, 0644)
	}
	writeFixtureFile(t, filepath.Join(workdir, ".nself", "generated", "routes.json"), "{}\n", 0644)
	return workdir, dir
}

func exists(p string) bool { _, err := os.Lstat(p); return err == nil }

func TestProxyRestoreMarker(t *testing.T) {
	workdir, dir := restoreProject(t, testRendererMarker)
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
		t.Fatal(err)
	}
	if exists(dir) {
		t.Fatalf("%s survived a cleanup with the marker present", dir)
	}
	if !exists(filepath.Join(workdir, ".nself", "generated", "routes.json")) {
		t.Fatal("cleanup removed a sibling generated file")
	}
	// A second build finds nothing to do.
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
		t.Fatalf("second cleanup: %v", err)
	}
}

func TestProxyRestoreNoMarker(t *testing.T) {
	for name, marker := range map[string]string{"absent": "", "foreign": "not ours\n"} {
		t.Run(name, func(t *testing.T) {
			workdir, dir := restoreProject(t, marker)
			if marker != "" {
				writeFixtureFile(t, filepath.Join(dir, proxyGeneratedMarker), marker, 0644)
			}
			before := proxyHashes(t, workdir)
			if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
				t.Fatalf("a foreign directory must warn, not fail: %v", err)
			}
			after := proxyHashes(t, workdir)
			if len(before) != len(after) {
				t.Fatalf("tree changed without a marker: %d files before, %d after", len(before), len(after))
			}
			for p, h := range before {
				if after[p] != h {
					t.Fatalf("%s changed", p)
				}
			}
		})
	}
}

func TestProxyRestoreTraefikProviderKeeps(t *testing.T) {
	workdir, dir := restoreProject(t, testRendererMarker)
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderTraefik); err != nil {
		t.Fatal(err)
	}
	if !exists(filepath.Join(dir, "dynamic.yml")) {
		t.Fatal("traefik still serves; its output must stay")
	}
}

func TestProxyRestoreSymlinkedDirKept(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlinks need privileges on windows")
	}
	workdir := t.TempDir()
	outside := t.TempDir()
	writeFixtureFile(t, filepath.Join(outside, "keep.txt"), "mine\n", 0644)
	writeFixtureFile(t, filepath.Join(outside, proxyGeneratedMarker), testRendererMarker, 0644)
	if err := os.MkdirAll(filepath.Join(workdir, ".nself", "generated"), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(outside, proxyOutputDir(workdir)); err != nil {
		t.Fatal(err)
	}
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
		t.Fatal(err)
	}
	if !exists(filepath.Join(outside, "keep.txt")) || !exists(filepath.Join(outside, proxyGeneratedMarker)) {
		t.Fatal("a symlinked output dir led the cleanup outside the project")
	}
}

func TestProxyRestoreSymlinkEntryRemovedNotFollowed(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlinks need privileges on windows")
	}
	workdir, dir := restoreProject(t, testRendererMarker)
	outside := filepath.Join(t.TempDir(), "target.txt")
	writeFixtureFile(t, outside, "mine\n", 0644)
	if err := os.Symlink(outside, filepath.Join(dir, "link")); err != nil {
		t.Fatal(err)
	}
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
		t.Fatal(err)
	}
	if exists(dir) || !exists(outside) {
		t.Fatalf("dir gone=%v, link target kept=%v", !exists(dir), exists(outside))
	}
}

func TestProxyRestorePlanModeOnlyRecords(t *testing.T) {
	workdir, dir := restoreProject(t, testRendererMarker)
	sink := newMemSink(workdir, "")
	if err := cleanupProviderOutput(sink, workdir, ProviderNginx); err != nil {
		t.Fatal(err)
	}
	if !exists(filepath.Join(dir, "dynamic.yml")) {
		t.Fatal("plan mode deleted a file")
	}
	if !sink.removed[sink.key(filepath.Join(dir, "dynamic.yml"))] {
		t.Fatal("plan mode did not record the removal")
	}
}

func TestProxyRestoreStaticDirAlsoCleaned(t *testing.T) {
	workdir, _ := restoreProject(t, testRendererMarker)
	static := proxyOutputPath(workdir, "traefik-static")
	writeFixtureFile(t, filepath.Join(static, "traefik.yml"), "# fixture\n", 0644)
	writeFixtureFile(t, filepath.Join(static, proxyGeneratedMarker), testRendererMarker, 0644)
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
		t.Fatal(err)
	}
	if exists(static) {
		t.Fatal("traefik-static survived")
	}
}

func TestProxyRestoreDanglingLinkPlanMode(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlinks need privileges on windows")
	}
	workdir, dir := restoreProject(t, testRendererMarker)
	if err := os.Symlink(filepath.Join(workdir, "gone"), filepath.Join(dir, "dangling")); err != nil {
		t.Fatal(err)
	}
	for name, sink := range map[string]Sink{"plan": newMemSink(workdir, ""), "apply": newDiskSink(workdir)} {
		if err := cleanupProviderOutput(sink, workdir, ProviderNginx); err != nil {
			t.Fatalf("%s: %v", name, err)
		}
	}
}

func TestProxyRestoreRootOwnedWarnsAndKeeps(t *testing.T) {
	if runtime.GOOS == "windows" || os.Geteuid() == 0 {
		t.Skip("needs unix permissions and a non-root user")
	}
	workdir, dir := restoreProject(t, testRendererMarker)
	if err := os.Chmod(dir, 0555); err != nil { // no unlink inside, as for a root-owned dir
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(dir, 0755) })
	if err := cleanupProviderOutput(newDiskSink(workdir), workdir, ProviderNginx); err != nil {
		t.Fatalf("a permission failure must warn, not fail the build: %v", err)
	}
	if !exists(filepath.Join(dir, proxyGeneratedMarker)) {
		t.Fatal("the marker must stay so the next build retries")
	}
}
